"""版本号解析与比较。

Windows 产品的版本号习惯是 ``major.minor.build.revision`` 四段十进制，
末尾段可以省略（省略视作 0），并且允许 ``1.2.3.4-beta.1`` 这样的预发布标签。
"""

_STRIP = "vV"


def normalize(text):
    """去掉可选的 ``v`` 前缀与首尾空白。"""
    value = str(text).strip()
    while value[:1] in _STRIP:
        value = value[1:]
    return value


def split_version(text):
    """把版本号拆成 ``(数字部分, 预发布标签)``。"""
    value = normalize(text)
    if "-" in value:
        numbers, prerelease = value.split("-", 1)
    else:
        numbers, prerelease = value, ""
    return numbers, prerelease.strip()


def parse_version(text):
    """把版本号拆成段列表。

    段之间用 ``.`` 分隔，不足四段的按原样返回（由调用方决定如何补齐）。
    """
    numbers, _prerelease = split_version(text)
    return numbers.split(".")


def compare_versions(left, right):
    """比较两个版本号。

    返回 ``-1`` / ``0`` / ``1``。预发布版本低于同号的正式版。
    """
    left_numbers, left_pre = split_version(left)
    right_numbers, right_pre = split_version(right)
    if left_numbers == right_numbers:
        if left_pre == right_pre:
            return 0
        if not left_pre:
            return 1
        if not right_pre:
            return -1
        return 1 if left_pre > right_pre else -1
    return 1 if left_numbers > right_numbers else -1


def is_upgrade(current, candidate):
    """``candidate`` 是否严格高于 ``current``。"""
    return compare_versions(candidate, current) > 0

"""把「想做什么」翻译成一组可以顺序执行的动作。

规划阶段**只读**：不允许创建目录、写文件或改清单。调用方可以先用
:func:`plan_transaction` 拿到计划并检查，再决定是否 :func:`transaction.apply_transaction`。
"""

import os
from collections import namedtuple

from . import layout, manifest
from .errors import PlanRejected
from .versions import is_upgrade, normalize

Action = namedtuple("Action", "kind relpath source")
Plan = namedtuple("Plan", "operation product version scope root actions files previous")

INSTALL = "install"
UNINSTALL = "uninstall"
_OPERATIONS = (INSTALL, UNINSTALL)


def _check_name(value, what):
    text = str(value or "").strip()
    if not text:
        raise ValueError("%s must not be empty" % what)
    if any(ch in text for ch in '\\/:*?"<>|'):
        raise ValueError("%s must not contain path separators: %r" % (what, value))
    return text


def _check_relpath(rel):
    key = layout.relative_key(rel)
    if not key or key.startswith("../") or "/../" in key:
        raise ValueError("payload path escapes the payload directory: %r" % (rel,))
    return key


def plan_transaction(operation, product, version=None, files=None, scope="machine", root=None):
    """规划一次安装或卸载。

    ``files`` 是 ``{相对路径: 源文件路径}``，只在 ``install`` 时使用。
    """
    if operation not in _OPERATIONS:
        raise ValueError("unknown operation: %r" % (operation,))
    product = _check_name(product, "product")
    root = layout.install_root(scope, base=root)
    data = manifest.read_manifest(root)
    current = manifest.get_product(data, product)

    if operation == UNINSTALL:
        if current is None:
            raise PlanRejected("not-installed", "%s is not installed" % product)
        old_version = current.get("version") or ""
        actions = []
        for rel in sorted(current.get("files") or []):
            actions.append(Action("remove", _check_relpath(rel), None))
        return Plan(UNINSTALL, product, old_version, scope, root,
                    tuple(actions), (), current)

    version = normalize(_check_name(version, "version"))
    if not isinstance(files, dict) or not files:
        raise ValueError("files must be a non-empty mapping of relpath -> source")

    if current is not None:
        installed = current.get("version") or ""
        if not is_upgrade(installed, version):
            raise PlanRejected(
                "downgrade",
                "%s %s is already installed; %s is not newer" % (product, installed, version))

    wanted = {}
    for rel, source in files.items():
        key = _check_relpath(rel)
        if key in wanted:
            raise ValueError("duplicate payload path: %r" % (key,))
        wanted[key] = source
    wanted = dict(sorted(wanted.items()))

    actions = [Action("write", rel, str(src)) for rel, src in wanted.items()]
    keep = set(wanted)
    if current is not None:
        for rel in sorted(current.get("files") or []):
            key = _check_relpath(rel)
            if key not in keep:
                actions.append(Action("remove", key, None))

    return Plan(INSTALL, product, version, scope, root, tuple(actions),
                tuple(wanted), current)


def destination(plan, action):
    """某个动作对应的绝对目标路径。"""
    return os.path.join(layout.payload_dir(plan.root, plan.product), action.relpath)

"""执行计划中的动作，并维护清单。

写入采用「同目录临时文件 + 原子替换」：目标位置要么是旧内容，要么是新内容，
不会出现半个文件。
"""

import os
import shutil
from collections import namedtuple

from . import manifest, planner

ApplyResult = namedtuple("ApplyResult", "operation product version applied deferred")

TMP_SUFFIX = ".winstall-part"


def _ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


def _put_file(source, destination):
    """把 ``source`` 放到 ``destination``（原子替换）。"""
    temporary = destination + TMP_SUFFIX
    shutil.copyfile(source, temporary)
    os.replace(temporary, destination)


def _delete_file(path):
    if os.path.isfile(path):
        os.remove(path)


def apply_transaction(plan):
    """顺序执行 ``plan`` 中的动作，然后更新清单。"""
    applied = []
    for action in plan.actions:
        target = planner.destination(plan, action)
        if action.kind == "write":
            _ensure_parent(target)
            _put_file(action.source, target)
        elif action.kind == "remove":
            _delete_file(target)
        else:
            raise ValueError("unknown action: %r" % (action.kind,))
        applied.append(action.relpath)

    data = manifest.read_manifest(plan.root)
    if plan.operation == planner.INSTALL:
        manifest.set_product(data, plan.product, plan.version, plan.files, [])
    else:
        manifest.drop_product(data, plan.product)
    manifest.write_manifest(plan.root, data)

    return ApplyResult(plan.operation, plan.product, plan.version,
                       tuple(applied), ())

"""安装清单（``installed.json``）的读写。

清单是安装状态的唯一权威记录，形状如下::

    {
      "schema": 1,
      "products": {
        "<product>": {
          "version": "1.2.3",
          "files": ["bin/app.exe", "etc/app.ini"],
          "pending_replace": ["bin/locked.dll"]
        }
      }
    }

``pending_replace`` 记录那些**因为被其它进程占用而暂时无法替换**的文件。
它们仍然以旧内容留在原处，等待下一次执行时完成替换。
"""

import json
import os

from . import layout

SCHEMA = 1


def manifest_path(root):
    return os.path.join(root, layout.MANIFEST_NAME)


def empty():
    return {"schema": SCHEMA, "products": {}}


def read_manifest(root):
    """读取清单；不存在或损坏时返回空清单。"""
    path = manifest_path(root)
    if not os.path.isfile(path):
        return empty()
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return empty()
    if not isinstance(data, dict):
        return empty()
    data.setdefault("schema", SCHEMA)
    products = data.get("products")
    if not isinstance(products, dict):
        data["products"] = {}
    return data


def write_manifest(root, data):
    """原子写入清单。"""
    os.makedirs(root, exist_ok=True)
    path = manifest_path(root)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(data, fh, ensure_ascii=False, indent=2, sort_keys=True)
    os.replace(tmp, path)


def get_product(data, product):
    entry = (data.get("products") or {}).get(product)
    if not isinstance(entry, dict):
        return None
    return entry


def set_product(data, product, version, files, pending_replace=None):
    data.setdefault("products", {})[product] = {
        "version": str(version),
        "files": [layout.relative_key(f) for f in files],
        "pending_replace": [layout.relative_key(f) for f in (pending_replace or [])],
    }


def drop_product(data, product):
    (data.get("products") or {}).pop(product, None)

"""安装根的布局规则。

两个作用域（scope）互相独立：

* ``machine`` —— 整机安装，落在 ``%ProgramData%\\WInstall``
* ``user``    —— 单用户安装，落在 ``%LOCALAPPDATA%\\WInstall``

目录形状::

    <root>/
        installed.json            # 清单
        products/
            <product>/
                payload/          # 已安装的文件（升级时原地覆盖）
"""

import os

MANIFEST_NAME = "installed.json"
PRODUCTS_DIR = "products"

_MACHINE_FALLBACK = r"C:\ProgramData"
_USER_FALLBACK = r"C:\Users\Default\AppData\Local"


def install_root(scope="machine", base=None):
    """返回某个作用域的安装根。

    ``base`` 用于测试或便携部署：显式给出时直接作为根使用。
    """
    if base:
        return os.path.abspath(str(base))
    if scope == "machine":
        env = os.environ.get("ProgramData") or _MACHINE_FALLBACK
    elif scope == "user":
        env = os.environ.get("LOCALAPPDATA")
        if not env:
            profile = os.environ.get("USERPROFILE") or ""
            env = os.path.join(profile, "AppData", "Local") if profile else _USER_FALLBACK
    else:
        raise ValueError("unknown scope: %r" % (scope,))
    return os.path.join(env, "WInstall")


def products_root(root):
    return os.path.join(root, PRODUCTS_DIR)


def product_dir(root, product):
    return os.path.join(products_root(root), product)


def payload_dir(root, product):
    """产品载荷的落盘位置。升级时在原地覆盖，不保留旧版本目录。"""
    return os.path.join(product_dir(root, product), "payload")


def normalize_key(path):
    """把路径归一成比较用的键。

    Windows 的路径比较不区分大小写，分隔符也允许混用。
    """
    return os.path.normcase(os.path.normpath(str(path)))


def relative_key(relpath):
    """把载荷内的相对路径归一成 POSIX 风格，作为清单里的稳定键。"""
    return str(relpath).replace("\\", "/").strip("/")

